<?php
declare(strict_types=1);
require_once '../config/config.php';require_once '../includes/church-book-functions.php';requireLogin();cb_require_permission('wedding_vows.view');$conn->set_charset('utf8mb4');cb_load_dompdf();
use Dompdf\Dompdf;use Dompdf\Options;
$id=cb_int($_GET['id']??0);$r=$id>0?cb_fetch_one($conn,"SELECT * FROM wedding_vows WHERE id=?",'i',[$id]):null;if(!$r){http_response_code(404);exit('Wedding record not found.');}$site=cb_site_setting($conn,'site_name','Church Management System');$e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
$date=!empty($r['wedding_date'])?date('d F Y',strtotime($r['wedding_date'])):'—';$parentsG=trim((string)($r['groom_father']?:'').' / '.(string)($r['groom_mother']?:''),' /');$parentsB=trim((string)($r['bride_father']?:'').' / '.(string)($r['bride_mother']?:''),' /');
$html='<!doctype html><html><head><meta charset="utf-8"><style>@page{margin:36px 42px}body{font-family:DejaVu Serif,serif;color:#111;font-size:11px}h1,h2,p{text-align:center;margin:4px}h2{font-size:16px}h1{font-size:23px}.rule{border-top:2px solid #222;margin:14px 0 20px}.grid{width:100%;border-collapse:collapse}.grid td{width:50%;padding:8px 10px;border-bottom:1px dotted #999;vertical-align:top}.label{font-family:DejaVu Sans,sans-serif;font-size:8px;text-transform:uppercase;color:#666;font-weight:bold;display:block;margin-bottom:3px}.wide{padding:8px 10px;border-bottom:1px dotted #999}.vows-title{text-align:center;font-weight:bold;margin:25px 0 8px}.vows{border:1px solid #aaa;padding:15px;min-height:100px;white-space:pre-wrap}.sign{width:100%;margin-top:54px;border-collapse:separate;border-spacing:18px 34px}.sign td{width:50%;border-top:1px solid #111;text-align:center;padding-top:5px;font-size:9px}.remarks{margin-top:25px}.footer{text-align:center;font-size:8px;color:#777;margin-top:20px}</style></head><body>';
$html.='<h2>'.$e($site).'</h2><h1>Wedding Vows Record</h1><p>Register No: '.$e($r['register_no']?:'—').' &nbsp; | &nbsp; Certificate No: '.$e($r['certificate_no']?:'—').'</p><div class="rule"></div>';
$html.='<table class="grid"><tr><td><span class="label">Wedding Date</span>'.$e($date).'</td><td><span class="label">Venue</span>'.$e($r['venue']?:'—').'</td></tr><tr><td><span class="label">Groom</span>'.$e($r['groom_name']).'</td><td><span class="label">Bride</span>'.$e($r['bride_name']).'</td></tr><tr><td><span class="label">Groom\'s Parents</span>'.$e($parentsG?:'—').'</td><td><span class="label">Bride\'s Parents</span>'.$e($parentsB?:'—').'</td></tr><tr><td><span class="label">Ceremony Basis</span>'.$e($r['ceremony_type']).(!empty($r['marriage_licence_no'])?' · '.$e($r['marriage_licence_no']):'').'</td><td><span class="label">Status</span>'.$e($r['status']).'</td></tr><tr><td><span class="label">Witness 1</span>'.$e($r['witness_1']?:'—').'</td><td><span class="label">Witness 2</span>'.$e($r['witness_2']?:'—').'</td></tr><tr><td><span class="label">Officiating Minister</span>'.$e($r['officiant']?:'—').'</td><td><span class="label">Assisting Minister</span>'.$e($r['assisting_minister']?:'—').'</td></tr></table>';
$html.='<div class="wide"><span class="label">Scripture / Theme</span>'.$e($r['scripture_theme']?:'—').'</div><div class="vows-title">Vows / Declaration</div><div class="vows">'.nl2br($e($r['vows_text']?:'')).'</div><table class="sign">';foreach(array_chunk(cb_wedding_signature_lines($conn),2) as $sigRow){$html.='<tr><td>'.$e($sigRow[0]).'</td><td>'.$e($sigRow[1]??'').'</td></tr>';}$html.='</table>';
